# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: intake
def intake(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(gather(digest(shape(fold(raw)))))

